<?php use yii\grid\GridView;use yii\helpers\Html;$this->title='Магазин';?><div class="mb-3 d-flex gap-2"><?= Html::a('Категория',['category'],['class'=>'btn btn-outline-primary']) ?><?= Html::a('Товар',['product'],['class'=>'btn btn-primary']) ?></div><div class="card p-3 mb-4"><h3>Категории</h3><div class="d-flex gap-2 flex-wrap"><?php foreach($categories as $c):?><?= Html::a(Html::encode($c->name),['category','id'=>$c->id],['class'=>'btn btn-outline-light']) ?><?php endforeach;?></div></div><?= GridView::widget(['dataProvider'=>$dataProvider,'columns'=>['id','name',['attribute'=>'category_id','value'=>fn($m)=>$m->category?->name],'price','delivery_type','enabled:boolean',['class'=>yii\grid\ActionColumn::class,'template'=>'{update}','buttons'=>['update'=>fn($u,$m)=>Html::a('✎',['product','id'=>$m->id])]]]]) ?>